13	const CODEX_AUTH_FILENAME = 'auth.json';
14	const CODEX_SDK_PACKAGE_NAME = '@openai/codex-sdk';
15	
16	let codexDefaultWorkingDir: string | undefined;
17	
18	const CODEX_GRADING_OUTPUT_SCHEMA = {
19	  type: 'object',
20	  properties: {
21	    pass: {
22	      type: 'boolean',
23	    },
24	    score: {
25	      type: 'number',
26	    },
27	    reason: {
28	      type: 'string',
29	    },
30	  },
31	  required: ['pass', 'score', 'reason'],
32	  additionalProperties: false,
33	} as const;
