10	/**
11	 * Creates a deferred promise that can be resolved or rejected externally.
12	 * Useful for controlling async flow in tests.
13	 */
14	export function createDeferred<T>(): {
15	  promise: Promise<T>;
16	  resolve: (value: T) => void;
17	  reject: (reason?: unknown) => void;
18	} {
19	  let resolve!: (value: T) => void;
20	  let reject!: (reason?: unknown) => void;
21	  const promise = new Promise<T>((promiseResolve, promiseReject) => {
22	    resolve = promiseResolve;
23	    reject = promiseReject;
24	  });
25	  return { promise, resolve, reject };
26	}
