141	export function mockGlobal<T>(name: string, value: T): () => void {
142	  const descriptor = Object.getOwnPropertyDescriptor(globalThis, name);
143	
144	  Object.defineProperty(globalThis, name, {
145	    configurable: true,
146	    value,
147	    writable: true,
148	  });
149	
150	  return () => {
151	    if (descriptor) {
152	      Object.defineProperty(globalThis, name, descriptor);
153	    } else {
154	      Reflect.deleteProperty(globalThis, name);
155	    }
156	  };
157	}
