3	/**
4	 * Interface for providers that need cleanup on process exit.
5	 */
6	interface CleanupProvider {
7	  shutdown(): Promise<void>;
8	}
9	
10	/**
11	 * Global registry of Python providers for cleanup on process exit.
12	 * Ensures no zombie Python processes are left running.
13	 */
14	class ProviderRegistry {
15	  private providers: Set<CleanupProvider> = new Set();
16	  private shutdownRegistered: boolean = false;
17	
18	  register(provider: CleanupProvider): void {
19	    this.providers.add(provider);
20	
21	    if (!this.shutdownRegistered) {
22	      this.registerShutdownHandlers();
23	      this.shutdownRegistered = true;
24	    }
25	  }
26	
27	  unregister(provider: CleanupProvider): void {
28	    this.providers.delete(provider);
29	  }
30	
31	  private registerShutdownHandlers(): void {
32	    let shuttingDown = false;
33	
34	    const shutdown = async (signal: string) => {
35	      if (shuttingDown) {
36	        return; // Prevent duplicate shutdown
37	      }
38	      shuttingDown = true;
39	
40	      logger.debug(`Received ${signal}, shutting down ${this.providers.size} Python providers...`);
41	
42	      await Promise.all(
43	        Array.from(this.providers).map((p) =>
44	          p.shutdown().catch((err) => {
45	            logger.error(`Error shutting down provider: ${err}`);
46	          }),
47	        ),
48	      );
49	
50	      logger.debug('Python provider shutdown complete');
51	    };
52	
53	    process.once('SIGINT', () => void shutdown('SIGINT'));
54	    process.once('SIGTERM', () => void shutdown('SIGTERM'));
55	    // Use beforeExit for async cleanup (exit event cannot await)
56	    process.once('beforeExit', () => void shutdown('beforeExit'));
57	  }
58	
59	  async shutdownAll(): Promise<void> {
60	    const results = await Promise.allSettled(Array.from(this.providers).map((p) => p.shutdown()));
61	
62	    // Log any failures but don't throw - cleanup should be defensive
63	    for (const result of results) {
64	      if (result.status === 'rejected') {
65	        logger.warn(`Error shutting down provider: ${result.reason}`);
66	      }
67	    }
68	
69	    this.providers.clear();
70	  }
71	}
